from pathlib import Path
R=Path(__file__).parent
f=R/'app.js';s=f.read_text(encoding='utf-8')
def sub(a,b):
 global s
 assert a in s,a[:100]
 s=s.replace(a,b)
sub("const DATA=JSON.parse(document.getElementById('project-data').textContent);","const BUNDLE=JSON.parse(document.getElementById('project-data').textContent);\nlet DATA=BUNDLE.variants.independent;")
sub("state={plan:'odd',overlay:true", "state={alignmentMode:'independent',plan:'odd',overlay:true")
sub("summary:'奇数层独立支撑用橙色，偶数层用紫色。每层按自己的轮廓、梁中心轴线与间距求解，并补接公共区与差异区的正交连接。'", "summary:p=>'仅两层几何重合区域要求对应连接；'+(DATA.meta.alignNonOverlap?'当前选“是”：非重合区尽量延续重合区网格。':'当前选“否”：非重合区按本层梁板独立布置。')+'挂梁端部及接墙柱端单独补查。'")
sub("long:'差异区域各层单独做支撑'", "long:'重合区连接，非重合区可选对齐'")
sub("<li>过渡处按各层实际支承连接横杆；剩余连接缺口列入复核。</li>","<li>挂梁端部、接墙柱端均补查支撑；连续相切梁段交界不重复作为梁端。</li><li>重合区的参数变化处仍分别选型计量，并检查对应连接。非重合区默认不强制对齐。</li>")
sub("<button class=\"example-button\" data-example=\"curve\">放大弧梁支撑 →</button>","<button class=\"example-button\" data-example=\"beamEnd\">查看挂梁端部支撑 →</button><button class=\"example-button\" data-example=\"curve\">放大弧梁支撑 →</button>")
sub("<li>只有两层都能实际放置、且梁板参数一致的坐标才成对保留。</li>","<li>同参数的公共区和参数变化的重合区，均检查支撑是否能够对应连接。</li><li>参数不同仍按各层自己的型号和索引值布置，数量分别计量。</li>")
sub("<li>公共区：两层梁板类型、截面/板厚及相对标高一致。</li>","<li>重合连接范围按两层有效梁板投影交集识别，包含参数一致区和参数变化区。</li><li>公共区：两层梁板类型、截面/板厚及相对标高一致，蓝色对位。</li>")
sub("<li>变化区：位置重叠，但类型或参数不同；两层各自计算。</li>","<li>变化区：位置重叠但参数不同，两层分别计算并检查对应连接。</li>")
sub("点选分区或支撑，查看层别、处理组、原图坐标和本层计算依据。","点选分区、梁端或支撑，查看重合区连接要求、端距和本层计算依据。")
sub("sel.kind==='nodes'||sel.kind==='issues'||sel.kind==='arcIntervals')", "sel.kind==='nodes'||sel.kind==='issues'||sel.kind==='arcIntervals'||sel.kind==='endSupports')")
sub("const columns={arcIntervals:","const columns={endSupports:['梁端编号','层别','构件 / 来源','端部类型','位置','固顶型号','中心退距 mm','端距上限 mm','实际支撑','状态'],arcIntervals:")
sub("['nodes','issues','arcIntervals'].includes(state.table)","['nodes','issues','arcIntervals','endSupports'].includes(state.table)")
sub("const names={arcIntervals:","const names={endSupports:'挂梁端部及接墙柱梁端支撑检查',arcIntervals:")
sub("if(state.table==='arcIntervals')cells=", "if(state.table==='endSupports')cells=[o.id,o.layer,o.owner+' / '+o.source,o.endType,o.side,o.model,o.inset,o.limit,o.node||'未放置',pill(o.placed&&o.endPass)];else if(state.table==='arcIntervals')cells=")
sub("o.cross?'十字':o.twoWay?'双向':'待复核'", "!o.requiredAlignment?'独立布置':!o.alignmentPaired?'重合待对应':o.cross?'十字':o.twoWay?'双向':'重合待连接'")
sub("function example(type){let p=plan();if(type==='standalone')", "function example(type){let p=plan();if(type==='beamEnd'){state.plan='even';state.overlay=false;setStep(5);state.table='endSupports';p=plan();const e=p.endSupports.find(e=>e.source==='37E0'&&e.side.endsWith('首端'))||p.endSupports.find(e=>e.placed);select('endSupports',e.id,true);return;}if(type==='standalone')")
sub("$('stepSummary').textContent=s.summary;", "$('stepSummary').textContent=typeof s.summary==='function'?s.summary(p):s.summary;$('alignmentMode').value=state.alignmentMode;$('alignmentDescription').textContent=DATA.meta.alignNonOverlap?'是：非重合区尽量延续重合区网格；重合区必需对位位置保持不变。':'否：仅重合区域要求对应连接；非重合区按本层独立布置。';")
sub("const mate=o.commonId?DATA.plans.find(x=>x.key!==p.key).nodes.find(n=>n.commonId===o.commonId):null;", "const mate=o.alignmentPairId?DATA.plans.find(x=>x.key!==p.key).nodes.find(n=>n.alignmentPairId===o.alignmentPairId):null;")
sub("['横杆方向数',o.degree]", "['对应连接要求',esc(o.alignmentPolicy)],['重合对位号',esc(o.alignmentPairId||'不要求 / 待对应')],['梁端支撑',o.terminal?esc(o.terminalRefs.join('、')):'常规网格'],['横杆连接数',o.degree]")
sub("else if(sel.kind==='arcIntervals'){", "else if(sel.kind==='endSupports'){html+=detailPairs([['端部类型',esc(o.endType)],['关联梁',esc(o.owner+' / '+o.source)],['位置',esc(o.side)],['型号',esc(o.model)],['端部 X / Y',o.endAt.map(v=>fmt(v,2)).join(' / ')],['支撑中心 X / Y',o.at.map(v=>fmt(v,2)).join(' / ')],['中心退距',o.inset+' mm'],['索引扣减后上限',o.limit+' mm'],['实际支撑编号',esc(o.node||'尚未放置')],['端距检查',pill(o.placed&&o.endPass)],['对应连接',o.requiredAlignment?esc(o.alignmentPairId||'重合区待对应'):'非重合区按本层布置'],['索引来源',esc(o.cell)]])+`<p class=\"small-note\">本次测试按固顶 W=100 的半宽退中心：100 / 2 = 50mm，仍须满足本层索引−100上限。${esc(o.detection)}。端部记录数与支撑根数不同，同一支撑可能覆盖两个端部。</p>`;}else if(sel.kind==='arcIntervals'){")
sub("if(kind==='arcIntervals'){", "if(kind==='endSupports'){head=['梁端编号','层别','梁编号','来源','端部类型','位置','端部Xmm','端部Ymm','支撑中心Xmm','支撑中心Ymm','型号','中心退距mm','端距上限mm','实际支撑','重合区域','对应号','检查'];data=rows().map(o=>[o.id,o.layer,o.owner,o.source,o.endType,o.side,...o.endAt,...o.at,o.model,o.inset,o.limit,o.node,o.requiredAlignment?'是':'否',o.alignmentPairId||'',o.placed&&o.endPass?'通过':'待复核']);}else if(kind==='arcIntervals'){")
sub("铂悦府6号_叠加分层_${state.overlay?", "铂悦府6号_${state.alignmentMode==='aligned'?'不重合区对齐':'不重合区独立'}_叠加分层_${state.overlay?")
sub("$('prevStep').onclick=", "$('alignmentMode').onchange=e=>{state.alignmentMode=e.target.value;DATA=BUNDLE.variants[state.alignmentMode];state.selected=null;state.page=0;state.search='';$('search').value='';render();toast(DATA.meta.alignNonOverlap?'已切换为非重合区域尽量对齐的计算结果':'已切换为非重合区域独立布置的计算结果');};$('prevStep').onclick=")
sub("if(s>=2){const zones=", "if(s>=2){out.push(`<path d=\"${DATA.overlay.requiredOverlapPath}\" fill=\"none\" stroke=\"#448e80\" stroke-opacity=\".7\" stroke-dasharray=\"3 3\" stroke-width=\".8\" vector-effect=\"non-scaling-stroke\" pointer-events=\"none\"/>`);const zones=")
sub("<circle r=\"105\" fill=\"transparent\"/>","<circle r=\"105\" fill=\"transparent\"/>${n.terminal?'<circle r=\"86\" fill=\"none\" stroke=\"#087d70\" stroke-width=\"1.4\" vector-effect=\"non-scaling-stroke\"/>':''}")
sub("if(state.selected?.kind==='beams')", "if(state.selected?.kind==='endSupports'){const e=objectFor(state.selected);if(e){out.push(`<path d=\"${path([e.endAt,e.at],false)}\" fill=\"none\" stroke=\"#087d70\" stroke-width=\"2\" vector-effect=\"non-scaling-stroke\"/><circle cx=\"${e.endAt[0]}\" cy=\"${-e.endAt[1]}\" r=\"60\" fill=\"none\" stroke=\"#087d70\" vector-effect=\"non-scaling-stroke\"/>`);}}if(state.selected?.kind==='beams')")
sub("<b>本次重新叠加</b>","<b>对齐范围与梁端</b><p>仅两层几何重合区域必须对应连接，包含同参数公共区和参数变化的重合区。不重合区域默认独立，可选择尽量延续重合区网格；切换选项不会改变重合区必需对位坐标。</p><p>挂梁端、接墙柱梁端纳入逐段端部检查；相切连续处不重复视作端部。按W100的半宽退中心50mm作为测试候选，端距仍按本层索引−100复核。墙柱遮挡、轴线不兼容等未放置项另列。</p></div><div class=\"source-block\"><b>本次重新叠加</b>")
f.write_text(s,encoding='utf-8')
t=R/'template.html';h=t.read_text(encoding='utf-8')
h=h.replace('圆弧楼面、弧梁与单独梁已纳入重叠计算；弧梁按中心线弧长布点，变化区域各层独立。','挂梁端部单独补查；仅重合区域要求对应连接，不重合区域可选择独立布置或延续对齐。')
h=h.replace('<div class="curve-shortcuts">','<div class="alignment-control"><label for="alignmentMode">不重合区域是否对齐</label><select id="alignmentMode" aria-label="不重合区域是否对齐"><option value="independent" selected>否（默认，按本层独立）</option><option value="aligned">是（尽量延续重合区网格）</option></select><span id="alignmentDescription">仅重合区域要求对应连接</span></div><div class="curve-shortcuts">')
h=h.replace('<span>本次补算</span>','<span>本次补算</span><button class="button" data-example="beamEnd">挂梁端部支撑 ↗</button>')
h=h.replace('橙 / 紫区分层计算，蓝区每层各一套','橙 / 紫分层计量，重合处仍需对应连接')
h=h.replace('<button data-table="arcIntervals">','<button data-table="endSupports">梁端支撑</button><button data-table="arcIntervals">')
h=h.replace('<option>连接构造</option>','<option>连接构造</option><option>梁端检查</option>')
h=h.replace('<span><i class="swatch issue"></i>待复核</span>','<span><i style="border:1px solid #087d70;border-radius:50%" class="swatch"></i>梁端支撑</span><span><i class="swatch issue"></i>待复核</span>')
t.write_text(h,encoding='utf-8')
with (R/'style.css').open('a',encoding='utf-8') as c:c.write('\n.alignment-control{display:flex;align-items:center;flex-wrap:wrap;gap:12px;padding:11px 14px;border:1px solid #cddfd7;background:#edf4ee;border-radius:8px;margin:0 0 12px}.alignment-control label{font-size:12px;font-weight:600;color:#315b4a}.alignment-control select{font-size:12px;padding:7px 10px}.alignment-control span{font-size:10px;color:#6d8575}.table-controls{flex-wrap:wrap}.segmented.small{flex-wrap:wrap}.segmented.small button{padding-left:9px;padding-right:9px}\n')
print('Beam end table and computed alignment-mode selector prepared')
